using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Linq;using BepInEx;using UnityEngine;using UnityEngine.UI;using Jotunn.Managers;using RunicLilyPads;using HarmonyLib;
[BepInPlugin("chazman.LilySmoke","Arcane lily validation","1.0.0")][BepInDependency("chazman.RunicLilyPads")]
public class LilySmoke:BaseUnityPlugin{
 bool ready;int errors;string root;const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 void Awake(){root=Path.GetFullPath(Path.Combine(Paths.BepInExRootPath,".."));Utils.SetSaveDataPath(root+"/saves");PrefabManager.OnVanillaPrefabsAvailable+=()=>ready=true;StartCoroutine(Run());}
 void Check(bool ok,string text){if(!ok)errors++;Logger.LogInfo((ok?"LILY PASS ":"LILY FAIL ")+text);}
 object Call(ArcaneLily target,string name,params object[] args)=>typeof(ArcaneLily).GetMethod(name,Hidden).Invoke(target,args);
 IEnumerator Run(){while(!ready)yield return null;
 if(Environment.GetEnvironmentVariable("LILY_MODE")=="server"){yield return Server();yield break;}
 bool client=Environment.GetEnvironmentVariable("LILY_MODE")=="client";
 if(client){var profile=new PlayerProfile("ivy_network",FileHelpers.FileSource.Local);profile.SetName("LilyTest");profile.m_firstSpawn=false;profile.Save();Game.SetProfile("ivy_network",FileHelpers.FileSource.Local);var fejd=FindObjectOfType<FejdStartup>();AccessTools.Property(typeof(FejdStartup),"ServerPassword").SetValue(null,"ivytest123");AccessTools.Field(typeof(FejdStartup),"m_joinServer").SetValue(fejd,new ServerJoinData(new ServerJoinDataDedicated("127.0.0.1:2476")));AccessTools.Field(typeof(FejdStartup),"m_instantStart").SetValue(fejd,true);fejd.JoinServer();}
 else {var world=World.GetCreateWorld("IvyValidation",FileHelpers.FileSource.Local);Game.SetProfile("ivy_validation",FileHelpers.FileSource.Local);ZNet.SetServer(true,false,false,"IvyValidation","",world);ZNet.ResetServerHost();AccessTools.Method(typeof(FejdStartup),"LoadMainScene").Invoke(FindObjectOfType<FejdStartup>(),null);}
 float end=Time.realtimeSinceStartup+160;while(!Player.m_localPlayer&&Time.realtimeSinceStartup<end)yield return null;if(!Player.m_localPlayer){Check(false,"world loaded");Finish();yield break;}
 var p=Player.m_localPlayer;p.SetGodMode(true);foreach(var v in FindObjectsOfType<Valkyrie>())v.DropPlayer(true);p.SetIntro(false);p.GetComponent<Rigidbody>().isKinematic=true;
 var coord=File.ReadAllText(root+"/persisted-position.txt").Split(',');var pos=new Vector3(float.Parse(coord[0]),float.Parse(coord[1]),float.Parse(coord[2]));
 if(File.Exists(root+"/lily-position.txt")){coord=File.ReadAllText(root+"/lily-position.txt").Split(',');pos=new Vector3(float.Parse(coord[0]),float.Parse(coord[1]),float.Parse(coord[2]));}
 p.transform.position=pos+Vector3.back*2;p.GetComponent<Rigidbody>().position=p.transform.position;yield return new WaitForSecondsRealtime(5);
 if(client){Check(!ZNet.instance.IsServer()&&ZNet.GetConnectionStatus()==ZNet.ConnectionStatus.Connected,"genuinely joined separate dedicated server");var list=FindObjectsOfType<ArcaneLily>();Check(list.Length>=3,"existing lilies reach joined client");if(list.Length>0){var target=list.First(t=>t.name.StartsWith("piece_arcanedecor_lily_arcane_003"));p.transform.position=target.transform.position+Vector3.back;p.GetComponent<Rigidbody>().position=p.transform.position;if(Environment.GetEnvironmentVariable("LILY_RECONNECT")=="1")Check(Mathf.Abs(target.GetComponent<ZNetView>().GetZDO().GetFloat("wg_lily_size",0)-1.65f)<.001f,"client changes survive real reconnect");
 GameCamera.instance.enabled=false;var f=target.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith("whitelilly_"));var camera=GameCamera.instance.transform;camera.position=f.bounds.center+new Vector3(0,1,-2);camera.LookAt(f.bounds.center);Physics.SyncTransforms();var hoverArgs=new object[]{null,null};AccessTools.Method(typeof(Player),"FindHoverObject").Invoke(p,hoverArgs);var hovered=hoverArgs[0] as GameObject;Check(hovered&&hovered.GetComponentInParent<ArcaneLily>()==target,"native hover selects walk-through lily (triggers="+Physics.queriesHitTriggers+")");
 Check(target.Interact(p,false,false),"joined client first interaction");Call(target,"SetHex","#00FFFF");Call(target,"SetSize",1.65f);Call(target,"SetLight",1.2f);Call(target,"Save");yield return new WaitForSecondsRealtime(3);Check(Mathf.Abs(target.GetComponent<ZNetView>().GetZDO().GetFloat("wg_lily_size",0)-1.65f)<.001f,"joined client edit committed");Call(target,"Open");yield return null;CaptureMenu();Call(target,"Cancel");CaptureFlower(target);}yield return new WaitForSecondsRealtime(6);Finish();yield break;}
 if(File.Exists(root+"/lily-saved.txt")){var saved=FindObjectsOfType<ArcaneLily>();Check(saved.Length>=3,"three lilies survive process restart");foreach(var t in saved){Check(t.GetComponent<ZNetView>().GetZDO().GetFloat("wg_lily_size",0)==1.5f,"size persisted "+t.name);Check(t.GetComponent<ZNetView>().GetZDO().GetFloat("wg_lily_b",0)==1,"color persisted "+t.name);}if(saved.Length>0){var t=saved[0];p.transform.position=t.transform.position+Vector3.back;p.GetComponent<Rigidbody>().position=p.transform.position;Call(t,"Open");yield return null;CaptureMenu();Call(t,"Cancel");CaptureFlower(t);}Finish();yield break;}
 // Move to a clear patch in the copied world; only this disposable world is changed.
 pos+=Vector3.right*35;for(int i=0;i<40&&Location.IsInsideNoBuildLocation(pos);i++)pos+=Vector3.right*15;
 p.transform.position=pos+Vector3.back*2;p.GetComponent<Rigidbody>().position=p.transform.position;yield return new WaitForSecondsRealtime(3);if(Heightmap.GetHeight(pos,out var ground))pos.y=ground+.3f;
 var pond=Instantiate(PrefabManager.Instance.GetPrefab("piece_arcanedecor_pond_round"),pos,Quaternion.identity);yield return new WaitForSecondsRealtime(2);File.WriteAllText(root+"/lily-position.txt",pos.x+","+pos.y+","+pos.z);
 p.transform.position=pos+Vector3.back*2;p.GetComponent<Rigidbody>().position=p.transform.position;GameCamera.instance.enabled=false;
 for(int stage=1;stage<=3;stage++){
 string id="piece_arcanedecor_lily_arcane_00"+stage;var prefab=PrefabManager.Instance.GetPrefab(id);Check(prefab&&prefab.GetComponent<ArcaneLily>()&&!prefab.GetComponent<GardenFlowerScale>(),"independent new prefab "+stage);
 var source=PrefabManager.Instance.GetPrefab("piece_arcanedecor_lily_white_00"+stage);Check(!source.GetComponent<ArcaneLily>()&&source.GetComponent<GardenFlowerScale>(),"original white lily unchanged "+stage);
 ExportIcon(prefab.GetComponent<Piece>().m_icon,"icon-"+stage);
 Hammer(prefab,pos+Vector3.forward*1.2f);
 var go=Instantiate(prefab,pos+Vector3.right*(stage-2)*1.3f,Quaternion.identity);yield return null;yield return null;var lily=go.GetComponent<ArcaneLily>();var flower=go.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith("whitelilly_"));
 Check(go.GetComponentsInChildren<Collider>().All(c=>c.isTrigger||c.gameObject.layer==LayerMask.NameToLayer("piece_nonsolid")),"walk-through colliders "+stage);
 Check(lily.Interact(p,false,false),"first interaction opens "+stage);yield return null;var canvas=FindObjectOfType<GardenMenuCursor>().GetComponent<Canvas>();Check(canvas.GetComponentsInChildren<Image>().First().color.a==1,"opaque menu");
 foreach(var hex in new[]{"#FF0000","#00FF00","#0000FF"}){Call(lily,"SetHex",hex);var block=new MaterialPropertyBlock();flower.GetPropertyBlock(block,1);ColorUtility.TryParseHtmlString(hex,out var expected);Check(block.GetColor("_Color")==expected,"petal RGB "+hex);}
 var foliage=new MaterialPropertyBlock();flower.GetPropertyBlock(foliage,0);Check(foliage.isEmpty,"foliage material unchanged");
 Call(lily,"SetLight",0f);Check(!go.GetComponentInChildren<Light>().enabled,"light off");Call(lily,"SetLight",2f);Call(lily,"SetGlow",3f);Call(lily,"SetSize",1.5f);Check(go.transform.Find("lily_visual/floating_lily").localScale.x==.75f,"independent size preview");
 if(stage==3){ScreenCapture.CaptureScreenshot(root+"/menu.png");yield return null;}
 Call(lily,"Cancel");Check(go.transform.Find("lily_visual/floating_lily").localScale.x==.5f,"Cancel restores size");yield return null;Check(!GardenMenuCursor.IsOpen,"closed menu removed");
 Call(lily,"Open");Call(lily,"SetHex","#AA55FF");Call(lily,"SetSize",1.5f);Call(lily,"SetGlow",2f);Call(lily,"SetLight",.7f);Call(lily,"Save");yield return null;
 Check(go.GetComponent<ZNetView>().GetZDO().GetFloat("wg_lily_size",0)==1.5f,"host saves settings");
 var second=Instantiate(prefab,pos+Vector3.forward,Quaternion.identity);yield return null;Check(second.GetComponentsInChildren<MeshFilter>().Last().sharedMesh==go.GetComponentsInChildren<MeshFilter>().Last().sharedMesh,"mesh shared between instances");Check(!second.GetComponent<ArcaneLily>().Interact(p,true,false),"hold does not reopen");ZNetScene.instance.Destroy(second);yield return null;
 }
 var targets=FindObjectsOfType<ArcaneLily>();var update=typeof(ArcaneLily).GetMethod("Update",Hidden);var checkField=typeof(ArcaneLily).GetField("nextCheck",Hidden);foreach(var t in targets)checkField.SetValue(t,float.MaxValue);var action=(Action)Delegate.CreateDelegate(typeof(Action),targets[0],update);var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<100000;i++)action();watch.Stop();Logger.LogInfo("LILY PERF 100000 idle ticks "+watch.Elapsed.TotalMilliseconds+" ms (CPU method only)");
 Game.instance.SavePlayerProfile(true);AccessTools.Method(typeof(ZNet),"SaveWorld").Invoke(ZNet.instance,new object[]{false});File.WriteAllText(root+"/lily-saved.txt","saved");yield return new WaitForSecondsRealtime(3);Finish();
 }
 void Hammer(GameObject prefab,Vector3 aim){
 var p=Player.m_localPlayer;var camera=GameCamera.instance.transform;
 p.AddKnownItem(PrefabManager.Instance.GetPrefab("Wood").GetComponent<ItemDrop>().m_itemData);p.AddKnownItem(PrefabManager.Instance.GetPrefab("Dandelion").GetComponent<ItemDrop>().m_itemData);p.SetNoPlacementCost(true);AccessTools.Method(typeof(Player),"UpdateKnownRecipesList").Invoke(p,null);
 var table=PrefabManager.Instance.GetPrefab("Hammer").GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces;AccessTools.Method(typeof(Player),"SetPlaceMode").Invoke(p,new object[]{table});var piece=prefab.GetComponent<Piece>();p.SetBuildCategory(piece.m_category);p.SetSelectedPiece(piece);
 camera.position=aim+new Vector3(0,2,-2);camera.LookAt(aim);Physics.SyncTransforms();AccessTools.Method(typeof(Player),"UpdatePlacementGhost").Invoke(p,new object[]{false});var status=(Player.PlacementStatus)AccessTools.Field(typeof(Player),"m_placementStatus").GetValue(p);Check(status==Player.PlacementStatus.Valid,"native lily water placement "+piece.name+" status="+status);
 var ghost=(GameObject)AccessTools.Field(typeof(Player),"m_placementGhost").GetValue(p);if(status==Player.PlacementStatus.Valid){var before=FindObjectsOfType<ArcaneLily>();p.PlacePiece(piece,ghost.transform.position,ghost.transform.rotation,false);var added=FindObjectsOfType<ArcaneLily>().FirstOrDefault(t=>t.gameObject!=ghost&&!before.Contains(t));Check(added,"native hammer places arcane lily");if(added)ZNetScene.instance.Destroy(added.gameObject);}
 AccessTools.Method(typeof(Player),"SetPlaceMode").Invoke(p,new object[]{null});
 }
 void CaptureMenu(){
 var canvas=FindObjectOfType<GardenMenuCursor>().GetComponent<Canvas>();var parts=canvas.GetComponentsInChildren<Transform>();foreach(var part in parts)part.gameObject.layer=30;
 var go=new GameObject("menu capture");var cam=go.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.2f,.3f,.35f);cam.cullingMask=1<<30;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();CaptureCamera(cam,1280,720,"menu");Destroy(go);
 }
 void CaptureFlower(ArcaneLily lily){var visual=lily.transform.Find("lily_visual");var transforms=visual.GetComponentsInChildren<Transform>();var layers=transforms.Select(t=>t.gameObject.layer).ToArray();foreach(var t in transforms)t.gameObject.layer=30;
 var flower=visual.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith("whitelilly_"));var b=flower.bounds;var go=new GameObject("flower capture");var cam=go.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.clear;cam.cullingMask=1<<30;cam.orthographic=true;cam.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.6f;cam.transform.position=b.center+new Vector3(0,2,-3);cam.transform.LookAt(b.center);CaptureCamera(cam,512,512,"flower-purple");Destroy(go);for(int i=0;i<transforms.Length;i++)transforms[i].gameObject.layer=layers[i];}
 void CaptureCamera(Camera cam,int w,int h,string name){var rt=new RenderTexture(w,h,24);cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(w,h,TextureFormat.RGBA32,false);texture.ReadPixels(new Rect(0,0,w,h),0,0);texture.Apply();File.WriteAllBytes(root+"/"+name+".png",ImageConversion.EncodeToPNG(texture));RenderTexture.active=old;cam.targetTexture=null;rt.Release();Destroy(rt);Destroy(texture);}
 void ExportIcon(Sprite icon,string name){var rt=RenderTexture.GetTemporary(icon.texture.width,icon.texture.height,0,RenderTextureFormat.ARGB32);Graphics.Blit(icon.texture,rt);var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes(root+"/"+name+".png",ImageConversion.EncodeToPNG(tex));RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Destroy(tex);}
 IEnumerator Server(){float end=Time.realtimeSinceStartup+260;while(Time.realtimeSinceStartup<end){if(ZDOMan.instance!=null&&ZNet.instance&&ZNet.instance.GetPeers().Any(p=>p.IsReady())){var list=new List<ZDO>();int index=0;while(!ZDOMan.instance.GetAllZDOsWithPrefabIterative("piece_arcanedecor_lily_arcane_003",list,ref index)){}if(list.Any(z=>Math.Abs(z.GetFloat("wg_lily_size",0)-1.65f)<.001f&&z.GetFloat("wg_lily_g",0)==1)){Check(true,"separate dedicated server observes client size and color");File.WriteAllText(root+"/network-observed.txt","PASS");yield break;}}yield return new WaitForSecondsRealtime(1);}Check(false,"server observation timeout");}
 void Finish(){Logger.LogInfo("LILY COMPLETE errors="+errors);Application.Quit(errors==0?0:1);}
}
